pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function testFuzz_property(address someAddress, uint256 someId, bytes calldata someData) public {
        bytes4 result = c.onERC721Received(someAddress, someAddress, someId, someData);

        assertEq(result, c.onERC721Received.selector);
    }
}
